use xiom.io;
fn double(x: Int) -> Int {
  return x * 2;
}

fn add_ten(x: Int) -> Int {
  return x + 10;
}

fn halve(x: Int) -> Int {
  return x / 2;
}

fn square(x: Int) -> Int {
  return x * x;
}

fn main() {
  let input = 4;
  let step1 = double(input);
  let step2 = add_ten(step1);
  let step3 = square(step2);
  let step4 = halve(step3);
  io.println("Assembly line complete!");
}
